INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist Benutzerfreundlichkeit immer gleichbedeutend mit einer intuitiven Bedienung?', 2, '[{"text": "Nein", "correct": true, "because": "Intuitivität ist nur ein Aspekt, Effizienz zählt ebenso"}, {"text": "Ja", "correct": false, "because": "Benutzerfreundlichkeit umfasst mehr als Intuition"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Barrierefreiheit die Entwicklungskosten eines Projekts signifikant erhöhen?', 2, '[{"text": "Ja", "correct": true, "because": "Zusätzliche Anpassungen wie Screenreader-Kompatibilität erfordern Aufwand"}, {"text": "Nein", "correct": false, "because": "Kostensteigerung hängt von Planung ab, ist aber oft der Fall"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen aktuelle Trends in der Benutzerfreundlichkeit zwingend mit visueller Ästhetik verbunden sein?', 2, '[{"text": "Nein", "correct": true, "because": "Funktionalität und Klarheit stehen oft im Vordergrund"}, {"text": "Ja", "correct": false, "because": "Ästhetik ist sekundär zu Nutzbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Barrierefreiheit nur für Nutzer mit Behinderungen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Sie verbessert die Nutzung für alle, z. B. durch Klarheit"}, {"text": "Ja", "correct": false, "because": "Universeller Nutzen wird oft unterschätzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Können aktuelle Trends in der Benutzerfreundlichkeit die technische Performance eines Systems negativ beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. Animationen können Ladezeiten verlängern"}, {"text": "Nein", "correct": false, "because": "Einfluss ist möglich, aber nicht ausgeschlossen"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher aktuelle Trend in der Benutzerfreundlichkeit zielt besonders auf die Reduktion kognitiver Belastung ab?', 3, '[{"text": "Minimalistisches Design", "correct": true, "because": "Weniger Elemente erleichtern die Orientierung"}, {"text": "Bunte Farbpaletten", "correct": false, "because": "Ästhetik, keine kognitive Entlastung"}, {"text": "Komplexe Animationen", "correct": false, "because": "Kann ablenken statt helfen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium der Barrierefreiheit wird oft als Mindestanforderung für moderne Webanwendungen angesehen?', 2, '[{"text": "Tastaturnavigation", "correct": true, "because": "Ermöglicht Zugang ohne Maus"}, {"text": "Maximale Schriftgröße", "correct": false, "because": "Wichtig, aber nicht zentral"}, {"text": "Schnelle Ladezeiten", "correct": false, "because": "Performance, nicht Barrierefreiheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher aktuelle Trend in der Benutzerfreundlichkeit wird häufig mit mobilen Geräten in Verbindung gebracht?', 3, '[{"text": "Gestensteuerung", "correct": true, "because": "Touchscreens fördern intuitive Bedienung"}, {"text": "Hohe Farbkontraste", "correct": false, "because": "Barrierefreiheit, nicht mobil-spezifisch"}, {"text": "Statische Layouts", "correct": false, "because": "Weniger flexibel für Mobilgeräte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt der Barrierefreiheit wird in aktuellen Trends oft übersehen?', 3, '[{"text": "Kompatibilität mit assistiven Technologien", "correct": true, "because": "Z. B. Screenreader werden unterschätzt"}, {"text": "Farbkontrast", "correct": false, "because": "Häufig beachtet"}, {"text": "Textgröße", "correct": false, "because": "Standardmäßig berücksichtigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor der Benutzerfreundlichkeit hat in aktuellen Trends den größten Einfluss auf die Nutzerbindung?', 2, '[{"text": "Personalisierung", "correct": true, "because": "Individuelle Anpassung erhöht Zufriedenheit"}, {"text": "Maximale Feature-Anzahl", "correct": false, "because": "Überladung kann abschrecken"}, {"text": "Schnelle Installation", "correct": false, "because": "Sekundär zur Nutzung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche aktuellen Trends fördern die Benutzerfreundlichkeit moderner Anwendungen?', 4, '[{"text": "Intuitive Navigation", "correct": true, "because": "Erleichtert die Orientierung"}, {"text": "Dynamische Animationen", "correct": true, "because": "Verbessert Feedback"}, {"text": "Maximale Datenmenge", "correct": false, "because": "Überfordert Nutzer"}, {"text": "Konsistentes Design", "correct": true, "because": "Schafft Vertrautheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente der Barrierefreiheit sind in aktuellen Trends besonders betont?', 3, '[{"text": "Screenreader-Unterstützung", "correct": true, "because": "Fördert Zugang für Blinde"}, {"text": "Hohe Farbkontraste", "correct": true, "because": "Hilft bei Sehproblemen"}, {"text": "Schnelle Serverantwort", "correct": false, "because": "Performance, nicht Barrierefreiheit"}, {"text": "Tastaturbedienbarkeit", "correct": true, "because": "Unterstützt motorische Einschränkungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen entstehen durch aktuelle Trends in der Benutzerfreundlichkeit?', 4, '[{"text": "Erhöhter Entwicklungsaufwand", "correct": true, "because": "Komplexe Features benötigen Zeit"}, {"text": "Kollision mit Barrierefreiheit", "correct": true, "because": "Z. B. Animationen vs. Einfachheit"}, {"text": "Schnellere Markteinführung", "correct": false, "because": "Trends verzögern oft"}, {"text": "Technische Komplexität", "correct": true, "because": "Neue Technologien sind anspruchsvoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten aktuelle Trends in der Barrierefreiheit?', 3, '[{"text": "Breitere Nutzerbasis", "correct": true, "because": "Mehr Menschen können zugreifen"}, {"text": "Verbesserte SEO", "correct": true, "because": "Barrierefreie Sites ranken besser"}, {"text": "Geringerer Speicherbedarf", "correct": false, "because": "Nicht direkt verbunden"}, {"text": "Rechtliche Absicherung", "correct": true, "because": "Erfüllt gesetzliche Vorgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken unterstützen aktuelle Trends in der Benutzerfreundlichkeit?', 3, '[{"text": "Mikrointeraktionen", "correct": true, "because": "Verbessern Feedback"}, {"text": "Künstliche Intelligenz", "correct": true, "because": "Ermöglicht Personalisierung"}, {"text": "Maximale Code-Komprimierung", "correct": false, "because": "Technisch, nicht nutzerbezogen"}, {"text": "Responsive Design", "correct": true, "because": "Passt sich Geräten an"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Aktuelle Trends in der Benutzerfreundlichkeit priorisieren oft visuelles Design über Funktionalität. b) Barrierefreiheit wird zunehmend als Wettbewerbsvorteil gesehen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Design ist wichtig, aber Funktionalität zentral; Barrierefreiheit gewinnt an Relevanz"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist nicht allgemein wahr"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Barrierefreiheit kann durch komplexe Animationen verbessert werden. b) Benutzerfreundlichkeit wird durch klare Rückmeldungen gesteigert.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Animationen können stören, Rückmeldungen helfen"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Aktuelle Trends in der Benutzerfreundlichkeit fördern oft überladene Interfaces. b) Barrierefreiheit wird durch WCAG-Richtlinien unterstützt.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Überladung wird vermieden, WCAG ist Standard"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Benutzerfreundlichkeit kann durch zu viele Optionen beeinträchtigt werden. b) Barrierefreiheit hat keinen Einfluss auf die allgemeine Nutzererfahrung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überladung schadet, Barrierefreiheit verbessert Erfahrung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Aktuelle Trends in der Barrierefreiheit ignorieren mobile Nutzer. b) Benutzerfreundlichkeit profitiert von konsistentem Design.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Mobil ist zentral, Konsistenz hilft"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist der Darkmode ausschließlich eine ästhetische Entscheidung ohne funktionale Vorteile?', 2, '[{"text": "Nein", "correct": true, "because": "Er reduziert Augenbelastung und Stromverbrauch bei OLED"}, {"text": "Ja", "correct": false, "because": "Funktionale Vorteile sind nachweisbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Mikrointeraktionen die Benutzerfreundlichkeit eines Systems negativ beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Übermäßige oder schlecht gestaltete Animationen können ablenken"}, {"text": "Nein", "correct": false, "because": "Negative Effekte sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der Darkmode in jeder Anwendung standardmäßig implementiert werden, um modern zu wirken?', 2, '[{"text": "Nein", "correct": true, "because": "Relevanz hängt vom Nutzungskontext ab"}, {"text": "Ja", "correct": false, "because": "Modernität ist nicht zwingend an Darkmode gekoppelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Mikrointeraktionen immer auf visuelle Elemente wie Animationen beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Haptisches Feedback oder Töne sind ebenfalls Mikrointeraktionen"}, {"text": "Ja", "correct": false, "because": "Visuelle Elemente sind nur ein Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Darkmode automatisch mit einer höheren Barrierefreiheit verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Kontrastprobleme können Barrierefreiheit beeinträchtigen"}, {"text": "Ja", "correct": false, "because": "Barrierefreiheit erfordert spezifische Anpassungen"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt des Darkmode ist für die Benutzererfahrung am entscheidendsten?', 3, '[{"text": "Ausreichender Kontrast", "correct": true, "because": "Sichert Lesbarkeit und Zugänglichkeit"}, {"text": "Maximale Farbvielfalt", "correct": false, "because": "Vielfalt ist nicht primär"}, {"text": "Schnelle Umschaltzeit", "correct": false, "because": "Technisch, aber weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen Mikrointeraktionen in erster Linie?', 2, '[{"text": "Verbesserung der Nutzerführung", "correct": true, "because": "Sie geben Rückmeldung und Orientierung"}, {"text": "Erhöhung der Ladezeit", "correct": false, "because": "Ladezeit ist kein Ziel"}, {"text": "Reduktion der Funktionalität", "correct": false, "because": "Gegenteil ist der Fall"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderung tritt bei der Implementierung des Darkmode am häufigsten auf?', 3, '[{"text": "Anpassung bestehender Farbschemata", "correct": true, "because": "Inkonsistenzen müssen vermieden werden"}, {"text": "Verringerung der Codezeilen", "correct": false, "because": "Codeaufwand steigt oft"}, {"text": "Automatische Geräteerkennung", "correct": false, "because": "Technisch, aber sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Mikrointeraktion wird am häufigsten zur Bestätigung von Aktionen verwendet?', 2, '[{"text": "Kurze Animationen", "correct": true, "because": "Visuelle Rückmeldung ist intuitiv"}, {"text": "Lange Tonsequenzen", "correct": false, "because": "Töne sind weniger präzise"}, {"text": "Statische Texte", "correct": false, "because": "Weniger dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher technische Vorteil des Darkmode ist besonders bei mobilen Geräten relevant?', 3, '[{"text": "Geringerer Stromverbrauch", "correct": true, "because": "OLED-Displays profitieren stark"}, {"text": "Schnellere Datenübertragung", "correct": false, "because": "Unabhängig vom Darkmode"}, {"text": "Höhere Speicherkapazität", "correct": false, "because": "Kein Zusammenhang"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sollten bei der Gestaltung eines Darkmode berücksichtigt werden?', 4, '[{"text": "Hoher Farbkontrast", "correct": true, "because": "Sichert Lesbarkeit"}, {"text": "Reduzierte Helligkeit", "correct": true, "because": "Schont die Augen"}, {"text": "Maximale Farbsättigung", "correct": false, "because": "Kann Kontrastprobleme erzeugen"}, {"text": "Nutzeroption zum Umschalten", "correct": true, "because": "Fördert Flexibilität"}]'),
('2e7f8d1c-4b5a-11ed-bdc3-0242ac120002', 'Welche Vorteile bieten Mikrointeraktionen in einer Benutzeroberfläche?', 3, '[{"text": "Sofortige Rückmeldung", "correct": true, "because": "Bestätigt Aktionen"}, {"text": "Verbesserte Navigation", "correct": true, "because": "Leitet Nutzer subtil"}, {"text": "Erhöhte Serverlast", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Gesteigerte Interaktivität", "correct": true, "because": "Macht UI lebendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte des Darkmode könnten die Barrierefreiheit beeinträchtigen?', 4, '[{"text": "Unzureichender Kontrast", "correct": true, "because": "Erschwert Lesbarkeit"}, {"text": "Fehlende Farbanpassungen", "correct": true, "because": "Kann Sehbehinderte stören"}, {"text": "Schnelle Aktivierung", "correct": false, "because": "Technisch, nicht barrierebezogen"}, {"text": "Verwendung dunkler Schriften", "correct": true, "because": "Kann auf dunklem Grund unsichtbar sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einsatzmöglichkeiten haben Mikrointeraktionen in modernen Anwendungen?', 3, '[{"text": "Bestätigung von Button-Klicks", "correct": true, "because": "Gibt visuelles Feedback"}, {"text": "Anzeige von Ladezuständen", "correct": true, "because": "Informiert über Prozesse"}, {"text": "Erhöhung der Dateigröße", "correct": false, "because": "Kein direkter Zusammenhang"}, {"text": "Hervorhebung von Fehlern", "correct": true, "because": "Lenkt Aufmerksamkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen können bei der Implementierung des Darkmode auftreten?', 3, '[{"text": "Kompatibilität mit bestehendem Design", "correct": true, "because": "Farbwechsel erfordert Anpassung"}, {"text": "Hoher Testaufwand", "correct": true, "because": "Kontraste müssen geprüft werden"}, {"text": "Automatische Aktivierung", "correct": false, "because": "Option, kein Problem"}, {"text": "Konsistenz über Plattformen", "correct": true, "because": "Unterschiede erschweren Einheitlichkeit"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Der Darkmode reduziert den Energieverbrauch bei allen Display-Typen gleichermaßen. b) Mikrointeraktionen erhöhen die Benutzerbindung.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Darkmode wirkt bei OLED, Interaktionen fördern Engagement"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Mikrointeraktionen sollten immer auffällig und dominant sein. b) Der Darkmode kann bei schlechter Umsetzung die Lesbarkeit verschlechtern.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Interaktionen sollten subtil sein, Darkmode braucht Kontrast"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Darkmode ist für alle Nutzergruppen gleichermaßen vorteilhaft. b) Mikrointeraktionen können die Wahrnehmung der Systemgeschwindigkeit beeinflussen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Darkmode ist nicht universell, Interaktionen täuschen Schnelligkeit"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Mikrointeraktionen erhöhen zwangsläufig die Komplexität einer Anwendung. b) Der Darkmode wird zunehmend als Standard erwartet.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Komplexität ist optional, Darkmode wird oft erwartet"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Darkmode erfordert keine Anpassung an Barrierefreiheitsstandards. b) Mikrointeraktionen können auch haptisches Feedback umfassen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Darkmode muss barrierefrei sein, haptisches Feedback ist möglich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');
